import sys

def is_palindrome(s):
    return s == s[::-1]

def palindrome_degree(s):
    if not s:
        return 0
    if is_palindrome(s):
        return 1 + palindrome_degree(s[1:-1])
    return 0

def main():
    import sys
    s = sys.stdin.read().strip()
    total_degree = 0
    for i in range(1, len(s) + 1):
        total_degree += palindrome_degree(s[:i])
    print(total_degree)

if __name__ == "__main__":
    main()
